19	  private final List<ExportBlockEntity> blocks;
20	  private final @Nullable MeLink me;
21	  private final Runnable onStale;
22	  private final ResourceHandler<ItemResource> allBlocks;
23	  private final ResourceHandler<ItemResource> extractView =
24	      new DelegatingResourceHandler<>(this::liveHandler);
25	
26	  public OutputSink(List<ExportBlockEntity> inOrder, @Nullable MeLink me, Runnable onStale) {
27	    this.blocks = List.copyOf(inOrder);
28	    this.me = me;
29	    this.onStale = onStale;
30	    this.allBlocks =
31	        new CombinedResourceHandler<>(
32	            blocks.stream().map(ExportBlockEntity::externalHandler).toList());
33	  }
