1	package io.github.julianperge.modular_planters.multiblock;
2	
3	import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
4	import java.util.List;
5	import net.minecraft.core.BlockPos;
6	import net.minecraft.world.Containers;
7	import net.minecraft.world.item.ItemStack;
8	import net.neoforged.neoforge.transfer.CombinedResourceHandler;
9	import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
10	import net.neoforged.neoforge.transfer.ResourceHandler;
11	import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
12	import net.neoforged.neoforge.transfer.item.ItemResource;
13	import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
14	import net.neoforged.neoforge.transfer.transaction.Transaction;
15	import net.neoforged.neoforge.transfer.transaction.TransactionContext;
16	import org.jspecify.annotations.Nullable;
17	
18	public final class OutputSink {
19	  private final List<ExportBlockEntity> blocks;
20	  private final @Nullable MeLink me;
21	  private final Runnable onStale;
22	  private final ResourceHandler<ItemResource> allBlocks;
23	  private final ResourceHandler<ItemResource> extractView =
24	      new DelegatingResourceHandler<>(this::liveHandler);
25	
26	  public OutputSink(List<ExportBlockEntity> inOrder, @Nullable MeLink me, Runnable onStale) {
27	    this.blocks = List.copyOf(inOrder);
28	    this.me = me;
29	    this.onStale = onStale;
30	    this.allBlocks =
31	        new CombinedResourceHandler<>(
32	            blocks.stream().map(ExportBlockEntity::externalHandler).toList());
33	  }
34	
35	  private List<ExportBlockEntity> live() {
36	    return LiveBlocks.of(blocks, onStale);
37	  }
38	
39	  boolean allLive() {
40	    return LiveBlocks.allLive(blocks, onStale);
41	  }
42	
43	  // A combined handler fixes its slot count when it is built, so a removed block needs a new one
44	  // until the core rebuilds the pool.
45	  private ResourceHandler<ItemResource> liveHandler() {
46	    return allLive()
47	        ? allBlocks
48	        : new CombinedResourceHandler<>(
49	            live().stream().map(ExportBlockEntity::externalHandler).toList());
50	  }
51	
52	  private @Nullable MeLink liveMe() {
53	    if (me == null) {
54	      return null;
55	    }
56	    if (me.isRemoved()) {
57	      onStale.run();
58	      return null;
59	    }
60	    return me;
61	  }
62	
63	  public boolean hasRoomFor(List<ItemStack> stacks) {
64	    int[] remaining = new int[stacks.size()];
65	    for (int i = 0; i < stacks.size(); i++) {
66	      ItemStack stack = stacks.get(i);
67	      remaining[i] =
68	          stack.isEmpty()
69	              ? 0
70	              : stack.getCount() - meTakes(ItemResource.of(stack), stack.getCount(), true);
71	    }
72	    try (Transaction tx = Transaction.openRoot()) {
73	      // ME is asked about each stack on its own and keeps nothing, so stacks that share ME room can
74	      // both pass, and the part ME refuses later goes to the export blocks or is held in the
75	      // planter block.
76	      for (int i = 0; i < stacks.size(); i++) {
77	        if (remaining[i] > 0
78	            && insertIntoBlocks(ItemResource.of(stacks.get(i)), remaining[i], tx) < remaining[i]) {
79	          return false;
80	        }
81	      }
82	      return true;
83	    }
84	  }
85	
86	  public ItemStack insert(ItemStack stack) {
87	    if (stack.isEmpty()) {
88	      return ItemStack.EMPTY;
89	    }
90	    ItemResource resource = ItemResource.of(stack);
91	    int remaining = stack.getCount() - meTakes(resource, stack.getCount(), false);
92	    remaining -= insertIntoBlocks(resource, remaining, null);
93	    return remaining == 0 ? ItemStack.EMPTY : resource.toStack(remaining);
94	  }
95	
96	  public ResourceHandler<ItemResource> extractView() {
97	    return extractView;
98	  }
99	
100	  // ME calls must happen with no transaction open, so each slot gives up what ME says it will take
101	  // in one committed transaction, offers that to ME, and puts what ME refused back into the same
102	  // slot in a second one.
103	  public void moveExportsInto(MeLink me) {
104	    if (!me.online()) {
105	      return;
106	    }
107	    for (ExportBlockEntity block : live()) {
108	      ItemStacksResourceHandler storage = block.storage();
109	      for (int slot = 0; slot < storage.size(); slot++) {
110	        ItemResource resource = storage.getResource(slot);
111	        if (resource.isEmpty()) {
112	          continue;
113	        }
114	        int asked = (int) me.insertItem(resource, storage.getAmountAsInt(slot), true);
115	        if (asked == 0) {
116	          continue;
117	        }
118	        int taken;
119	        try (Transaction tx = Transaction.openRoot()) {
120	          taken = storage.extract(slot, resource, asked, tx);
121	          tx.commit();
122	        }
123	        int refused = taken - (int) me.insertItem(resource, taken, false);
124	        if (refused == 0) {
125	          continue;
126	        }
127	        int returned;
128	        try (Transaction tx = Transaction.openRoot()) {
129	          returned = storage.insert(slot, resource, refused, tx);
130	          tx.commit();
131	        }
132	        // The put-back fits because the slot just gave up at least that much of the same item and
133	        // nothing else writes to it during the ME call, so dropping the rest at the block only
134	        // keeps the items if another mod breaks that.
135	        if (returned < refused) {
136	          ItemStack lost = resource.toStack(refused - returned);
137	          BlockPos pos = block.getBlockPos();
138	          while (!lost.isEmpty()) {
139	            Containers.dropItemStack(
140	                block.getLevel(),
141	                pos.getX(),
142	                pos.getY(),
143	                pos.getZ(),
144	                lost.split(lost.getMaxStackSize()));
145	          }
146	        }
147	      }
148	    }
149	  }
150	
151	  public int fillPercent() {
152	    long stored = 0;
153	    long capacity = 0;
154	    for (ExportBlockEntity block : live()) {
155	      ItemStacksResourceHandler storage = block.storage();
156	      for (int slot = 0; slot < storage.size(); slot++) {
157	        stored += storage.getAmountAsLong(slot);
158	        capacity += storage.getCapacityAsLong(slot, storage.getResource(slot));
159	      }
160	    }
161	    return capacity == 0 ? 0 : (int) (stored * 100 / capacity);
162	  }
163	
164	  private int meTakes(ItemResource resource, int amount, boolean simulate) {
165	    MeLink link = liveMe();
166	    return link != null && link.online() ? (int) link.insertItem(resource, amount, simulate) : 0;
167	  }
168	
169	  private int insertIntoBlocks(
170	      ItemResource resource, int amount, @Nullable TransactionContext transaction) {
171	    int inserted = 0;
172	    for (ExportBlockEntity block : live()) {
173	      if (inserted == amount) {
174	        break;
175	      }
176	      inserted +=
177	          ResourceHandlerUtil.insertStacking(
178	              block.storage(), resource, amount - inserted, transaction);
179	    }
180	    return inserted;
181	  }
182	}
