358	  @Override
359	  public void preRemoveSideEffects(BlockPos pos, BlockState state) {
360	    if (level == null) {
361	      return;
362	    }
363	    for (SeedBin.Combo<ItemStack> combo : seeds.combos()) {
364	      dropAll(pos, combo.seed().copyWithCount(combo.count()));
365	    }
366	    seeds.clear();
367	    for (int slot = 0; slot < soilAndUpgrades.size(); slot++) {
368	      dropAll(pos, soilAndUpgrades.getResource(slot).toStack(soilAndUpgrades.getAmountAsInt(slot)));
369	      soilAndUpgrades.set(slot, ItemResource.EMPTY, 0);
370	    }
371	    heldOutputs.forEach(stack -> dropAll(pos, stack));
372	    heldOutputs.clear();
373	  }
