382	  @Override
383	  protected void saveAdditional(ValueOutput output) {
384	    super.saveAdditional(output);
385	    output.putString("status", status.name());
386	    if (!lastSoil.isEmpty()) {
387	      output.store("last_soil", ItemStack.CODEC, lastSoil);
388	    }
389	    ValueOutput.ValueOutputList bin = output.childrenList("seeds");
390	    for (int i = 0; i < seeds.size(); i++) {
391	      ValueOutput entry = bin.addChild();
392	      entry.store("seed", ItemStack.CODEC, seeds.seed(i));
393	      entry.putInt("progress", seeds.progress(i));
394	      entry.putBoolean("ready", seeds.ready(i));
395	    }
396	    // The save key keeps the name from before upgrades were called upgrades, so planter blocks
397	    // saved earlier load their soil and upgrades.
398	    soilAndUpgrades.serialize(output.child("soil_and_modules"));
399	    output.store("cloche_remainders", REMAINDERS_CODEC, clocheRemainders.snapshot());
400	    ValueOutput.TypedOutputList<ItemStack> held = output.list("held_outputs", ItemStack.CODEC);
401	    heldOutputs.forEach(held::add);
402	  }
