122	  // progress without ticking. The phase is the game time plus the Core's offset, and it spreads the
123	  // ME transfers of different Cores over different ticks.
124	  public void tick(ServerLevel level, long phase) {
125	    if (power == null || fertilizer == null || outputs == null || !allPartsLoaded(level)) {
126	      return;
127	    }
128	    MeLink link = onlineMe();
129	    if (link != null) {
130	      power.refillFrom(link);
131	    }
132	    TickContext context =
133	        new TickContext(
