165	  private static ResourceHandler<ItemResource> itemDoorway(
166	      FertilizerPool fertilizer, OutputSink outputs) {
167	    ResourceHandler<ItemResource> whole =
168	        new CombinedResourceHandler<>(fertilizer.insertView(), outputs.extractView());
169	    return new DelegatingResourceHandler<>(
170	        () ->
171	            fertilizer.allLive() && outputs.allLive()
172	                ? whole
173	                : new CombinedResourceHandler<>(fertilizer.insertView(), outputs.extractView()));
174	  }
