35	        public JsonObject json() {
36	            JsonObject j=new JsonObject();j.addProperty("revision",revision);j.addProperty("state",state);j.addProperty("error",error);
37	            j.addProperty("captured",captured);j.addProperty("total",views.size());j.addProperty("sha256",sha256);
