47	            HttpServer http=HttpServer.create(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0),0);
48	            http.setExecutor(Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"Structure Lab HTTP");t.setDaemon(true);return t;}));
49	            http.createContext("/rpc",exchange->{
50	                int status=200; JsonObject response;
