79	            case "blocks": return onServer(()->LabSession.blocks(request.has("query")?request.get("query").getAsString():""));
80	            case "inspect": return onServer(()->LabSession.inspect(request.getAsJsonArray("positions")));
81	            case "job": {if(job==null)throw new IllegalStateException("No job submitted");return job.json();}
82	            case "cancel": {if(job!=null)job.cancelled=true;return job==null?new JsonObject():job.json();}
83	            case "validate": {
84	                CompoundTag tag=onServer(()->LabSession.validate(Path.of(request.get("path").getAsString())));
