86	            }
87	            case "submit": {
88	                onServer(()->{LabSession.requireLab();return true;});
89	                if(!busy.compareAndSet(false,true))throw new IllegalStateException("A job is active; wait or cancel it");
90	                Job next;
91	                try{next=new Job();}catch(Exception e){busy.set(false);throw e;}
92	                job=next;
93	                IO.execute(()->runSubmission(next,request));return next.json();
94	            }
95	            case "recapture": {
96	                Job previous=job;
97	                if(previous==null||!previous.state.equals("complete"))throw new IllegalStateException("Complete a revision before recapturing");
98	                if(!previous.revision.equals(request.get("revision").getAsString()))throw new IllegalArgumentException("Stale revision");
99	                onServer(previous,()->{LabSession.requireLab();return true;});
100	                if(!busy.compareAndSet(false,true))throw new IllegalStateException("A job is active");
101	                try{
102	                    Job next=new Job();next.sha256=previous.sha256;
103	                    next.views=request.has("views")?expandViews(request.getAsJsonArray("views"),new CompoundTag()):previous.views.deepCopy();
104	                    Files.copy(previous.directory.resolve("structure.nbt"),next.directory.resolve("structure.nbt"));
105	                    next.state="capturing";job=next;persist(next);Minecraft.getInstance().execute(()->LabCapture.begin(next));return next.json();
106	                }catch(Exception e){busy.set(false);throw e;}
