128	            clientReady.get(30,TimeUnit.SECONDS);
129	            onServer(next,()->LabPlacement.begin(tag,next)).get(300,TimeUnit.SECONDS);
130	            if(next.cancelled)throw new CancellationException();
131	            next.state="capturing";persist(next);
132	            Minecraft.getInstance().execute(()->LabCapture.begin(next));
133	        }catch(Exception e){fail(next,e);}
134	    }
