145	            if(angles.isEmpty()){JsonObject a=new JsonObject();a.addProperty("id","default");a.add("yaw",pad.get("yaw"));a.add("pitch",pad.get("pitch"));angles.add(a);}
146	            Set<String> angleIds=new HashSet<>();
147	            for(JsonElement a:angles){
148	                JsonObject angle=a.getAsJsonObject(),v=pad.deepCopy();v.remove("angles");String aid=angle.get("id").getAsString();
149	                if(!aid.matches("[a-zA-Z0-9_-]{1,64}")||!angleIds.add(aid))throw new IllegalArgumentException("Angle IDs must be unique within a pad");
150	                v.addProperty("angle",aid);v.add("yaw",angle.get("yaw"));v.add("pitch",angle.get("pitch"));
151	                if(angle.has("fov"))v.add("fov",angle.get("fov"));
152	                if(!v.has("fov"))v.addProperty("fov",70);
153	                if(!v.has("eye_height"))v.addProperty("eye_height",1.62);
154	                if(v.has("render_distance")){
155	                    double distance=v.get("render_distance").getAsDouble();
156	                    if(!Double.isFinite(distance)||distance!=Math.rint(distance)||distance<4||distance>24)throw new IllegalArgumentException("Render distance must be an integer between 4 and 24 chunks");
157	                }
158	                double eye=v.get("eye_height").getAsDouble();
159	                if(!Double.isFinite(eye)||eye<0||eye>4)throw new IllegalArgumentException("Eye height must be between 0 and 4");
160	                JsonArray p=v.getAsJsonArray("position");if(p==null||p.size()!=3)throw new IllegalArgumentException("View needs a 3D position");
161	                for(JsonElement n:p)if(!Double.isFinite(n.getAsDouble())||Math.abs(n.getAsDouble())>2048)throw new IllegalArgumentException("Invalid view coordinates");
162	                float yaw=v.get("yaw").getAsFloat(),pitch=v.get("pitch").getAsFloat();int fov=v.get("fov").getAsInt();
163	                if(!Float.isFinite(yaw)||!Float.isFinite(pitch)||pitch < -90||pitch>90||fov<30||fov>110)throw new IllegalArgumentException("Invalid camera angles or FOV");
164	                views.add(v);
165	            }
166	        }
167	        if(views.size()>1024)throw new IllegalArgumentException("At most 1024 captured angles are supported");
168	        views.sort(Comparator.comparing(v->!(v.has("spawn")&&v.get("spawn").getAsBoolean())));
169	        JsonArray out=new JsonArray();views.forEach(out::add);return out;
170	    }
171	    public static void persist(Job j)throws Exception {
172	        Path temp=j.directory.resolve("manifest.tmp");Files.writeString(temp,GSON.toJson(j.json()));
173	        Files.move(temp,j.directory.resolve("manifest.json"),StandardCopyOption.REPLACE_EXISTING);
174	    }
175	    public static void fail(Job j,Throwable e){
176	        j.state=j.cancelled?"cancelled":"failed";j.error=message(e);
177	        j.cancelled=true; // Stop queued chunk work after an I/O or placement timeout.
178	        try{persist(j);}catch(Exception ignored){}busy.set(false);
179	        if(j.pauseBefore!=null)Minecraft.getInstance().execute(()->Minecraft.getInstance().options.pauseOnLostFocus=j.pauseBefore);
180	    }
181	    public static void complete(Job j){
182	        IO.execute(()->{
183	            try{
184	                j.state="complete";persist(j);
185	                Path latest=root.resolve("latest.json");String old=null;
186	                if(Files.exists(latest))old=JsonParser.parseString(Files.readString(latest)).getAsJsonObject().get("revision").getAsString();
187	                Files.writeString(latest,GSON.toJson(j.json()));
188	                if(old!=null&&!old.equals(j.revision)){
189	                    Path oldDir=root.resolve("revisions").resolve(old).normalize();
190	                    if(old.matches("[a-f0-9-]{36}")&&oldDir.getParent().equals(root.resolve("revisions"))&&Files.isDirectory(oldDir)){
191	                        try(var paths=Files.walk(oldDir)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}
192	                    }
193	                }
194	                busy.set(false);
195	            }catch(Exception e){fail(j,e);}
196	        });
